#include <gkyl_gyrokinetic_priv.h>

// Each entry supplies a local maximum and its definition. Add future rates here;
// storage, MPI reduction and component metadata follow this registry automatically.
struct gk_frequency_descriptor {
  const char *name, *definition;
  double (*calc)(gkyl_gyrokinetic_app *, struct gk_species *);
};

static double
gk_frequency_omegaH(gkyl_gyrokinetic_app *app, struct gk_species *gks)
{
  return gk_species_omegaH_frequency(app, gks, gks->f);
}

static double
gk_frequency_transit(gkyl_gyrokinetic_app *app, struct gk_species *gks)
{
  return gks->transit_frequency * gks->collisionless.scale_fac *
         gk_fdot_multiplier_get_time_dilation_scale_const(app, &gks->fdot_mult);
}

static const struct gk_frequency_descriptor frequency_registry[] = {
  {"omega_H",
   "Local omega_H stability estimate, including equation scaling; zero for Boltzmann/adiabatic fields. No CFL factor.",
   gk_frequency_omegaH},
  {"transit",
   "Resolved parallel transit estimate: max|v_parallel| * max|cell-average(C/(J B))| / L_z. L_z is the computational parallel extent of this block. Includes equation scaling; no 2*pi or CFL factor.",
   gk_frequency_transit}
};

enum { num_frequencies = sizeof frequency_registry / sizeof frequency_registry[0] };

void
gk_species_frequencies_init(gkyl_gyrokinetic_app *app, struct gk_species *gks)
{
  gks->frequencies_max = gkyl_dynvec_new(GKYL_DOUBLE, num_frequencies);
  gks->is_first_frequencies_write_call = true;

  // Geometry and velocity mapping are stationary. Compute this factor once,
  // on the host for both CPU and GPU runs, without retaining extra grid arrays.
  int nb = app->basis.num_basis;
  struct gkyl_array *cmag = gkyl_array_new(GKYL_DOUBLE, nb, app->local_ext.volume);
  struct gkyl_array *inv_jb = gkyl_array_new(GKYL_DOUBLE, nb, app->local_ext.volume);
  struct gkyl_array *parfac = gkyl_array_new(GKYL_DOUBLE, nb, app->local_ext.volume);
  gkyl_array_copy(cmag, app->gk_geom->geo_int.cmag);
  gkyl_array_copy(inv_jb, app->gk_geom->geo_int.jacobtot_inv);
  gkyl_dg_mul_op_range(&app->basis, 0, parfac, 0, cmag, 0, inv_jb, &app->local);
  double max_parfac = 0.0;
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &app->local);
  while (gkyl_range_iter_next(&iter)) {
    const double *coeff = gkyl_array_cfetch(parfac, gkyl_range_idx(&app->local, iter.idx));
    max_parfac = fmax(max_parfac, fabs(coeff[0]) / pow(sqrt(2.0), app->cdim));
  }
  int vdim = gks->grid_vel.ndim, zdir = app->cdim - 1;
  double vmax = fmax(fabs(gks->vel_map->vbounds[0]), fabs(gks->vel_map->vbounds[vdim]));
  gks->transit_frequency = vmax * max_parfac / (app->grid.upper[zdir] - app->grid.lower[zdir]);
  gkyl_array_release(parfac);
  gkyl_array_release(inv_jb);
  gkyl_array_release(cmag);

  // Flat, zero-based component keys are readable by existing msgpack readers.
  struct gkyl_msgpack_map_elem meta[3 + 2 * num_frequencies];
  char name_keys[num_frequencies][32], definition_keys[num_frequencies][32];
  meta[0] = gmpe_cval(
    "Description", "Maximum characteristic frequencies across MPI ranks within this block."
  );
  meta[1] = gmpe_cval("units", "1/s");
  meta[2] = gmpe_ival("numComponents", num_frequencies);
  for (int i = 0; i < num_frequencies; ++i) {
    snprintf(name_keys[i], sizeof name_keys[i], "component%d", i);
    snprintf(definition_keys[i], sizeof definition_keys[i], "component%dDefinition", i);
    meta[3 + 2 * i] = (struct gkyl_msgpack_map_elem){
      .key = name_keys[i],
      .elem_type = GKYL_MP_STRING,
      .cval = frequency_registry[i].name,
    };
    meta[4 + 2 * i] = (struct gkyl_msgpack_map_elem){
      .key = definition_keys[i],
      .elem_type = GKYL_MP_STRING,
      .cval = frequency_registry[i].definition,
    };
  }
  int lengths[] = {gks->io_meta_basic_len, app->gk_geom->io_meta_basic_len, 3 + 2 * num_frequencies};
  const struct gkyl_msgpack_map_elem *lists[] = {
    gks->io_meta_basic, app->gk_geom->io_meta_basic, meta
  };
  gks->frequencies_meta = gkyl_msgpack_create_union(3, lengths, lists);
}

void
gk_species_frequencies_calc(gkyl_gyrokinetic_app *app, struct gk_species *gks, double tm)
{
  double local[num_frequencies], global[num_frequencies];
  for (int i = 0; i < num_frequencies; ++i) {
    local[i] = frequency_registry[i].calc(app, gks);
  }
  gkyl_comm_allreduce_host(app->comm, GKYL_DOUBLE, GKYL_MAX, num_frequencies, local, global);
  gkyl_dynvec_append(gks->frequencies_max, tm, global);
}

void
gk_species_frequencies_write(gkyl_gyrokinetic_app *app, struct gk_species *gks)
{
  int rank;
  gkyl_comm_get_rank(app->comm, &rank);
  if (rank == 0) {
    const char *fmt = "%s-%s_frequencies_max.gkyl";
    int sz = gkyl_calc_strlen(fmt, app->name, gks->info.name);
    char filename[sz + 1];
    snprintf(filename, sizeof filename, fmt, app->name, gks->info.name);
    // A restarted run may enable this diagnostic for the first time.
    if (gks->is_first_frequencies_write_call || !gkyl_check_file_exists(filename)) {
      gkyl_dynvec_write_wmeta(gks->frequencies_max, filename, gks->frequencies_meta);
      gks->is_first_frequencies_write_call = false;
    } else {
      gkyl_dynvec_awrite(gks->frequencies_max, filename);
    }
  }
  gkyl_dynvec_clear(gks->frequencies_max);
  app->stat.n_diag_io += 1;
}

void
gk_species_frequencies_release(const struct gk_species *gks)
{
  gkyl_dynvec_release(gks->frequencies_max);
  gkyl_msgpack_data_release(gks->frequencies_meta);
}
"""Check the sheath frequency diagnostic, including restart and optional MPI.

Build rt_gk_sheath_1x2v_p1, then run this script from the repository root:
  python3 gyrokinetic/creg/check_gk_frequencies.py [--mpirun /path/to/mpirun]
Requires Python msgpack. Use LD_LIBRARY_PATH if build libraries are elsewhere.
"""

import argparse
import math
import os
from pathlib import Path
import struct
import subprocess
import tempfile

import msgpack


def read_dynvec(path):
    metadata, records = None, []
    with path.open("rb") as stream:
        while magic := stream.read(5):
            assert magic == b"gkyl0"
            version, kind, meta_size = struct.unpack("=QQQ", stream.read(24))
            assert (version, kind) == (1, 2)
            if meta_size:
                metadata = msgpack.unpackb(stream.read(meta_size))
            dtype, stride, count = struct.unpack("=QQQ", stream.read(24))
            assert (dtype, stride) == (2, 16)
            times = struct.unpack(f"={count}d", stream.read(8 * count))
            values = struct.unpack(f"={2 * count}d", stream.read(stride * count))
            records.extend(zip(times, zip(values[::2], values[1::2])))
    assert metadata["numComponents"] == 2
    assert metadata["units"] == "1/s"
    assert metadata["component0"] == "omega_H"
    assert metadata["component1"] == "transit"
    assert all(metadata[f"component{i}Definition"] for i in range(2))
    assert records
    # This input has identity geometry, v_parallel,max=4*sqrt(Te/me), Lz=4 m.
    expected_transit = math.sqrt(40 * abs(metadata["charge"]) / metadata["mass"])
    for time, (omega_h, transit) in records:
        assert math.isfinite(time) and time >= 0
        assert math.isfinite(omega_h) and omega_h > 0
        assert math.isclose(transit, expected_transit, rel_tol=1e-12)
    return records


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--executable", type=Path,
                        default=Path("build/gyrokinetic/creg/rt_gk_sheath_1x2v_p1"))
    parser.add_argument("--mpirun")
    args = parser.parse_args()
    executable = args.executable.resolve()
    env = os.environ.copy()
    build = executable.parents[2]
    env["LD_LIBRARY_PATH"] = ":".join(
        [str(build / solver) for solver in ("core", "moments", "vlasov", "gyrokinetic")]
        + [env.get("LD_LIBRARY_PATH", "")]
    )

    def run(directory, *options, mpi=False):
        command = [str(executable), "-s10000", *options]
        if mpi:
            command = [args.mpirun, "-np", "2", *command, "-M", "-c", "2"]
        result = subprocess.run(command, cwd=directory, env=env, text=True,
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        assert result.returncode == 0, result.stdout

    filename = executable.name + "-elc_frequencies_max.gkyl"
    with tempfile.TemporaryDirectory() as directory:
        run(directory)
        path = Path(directory) / filename
        serial = read_dynvec(path)
        assert not list(Path(directory).glob("*-ion_frequencies_max.gkyl"))
        original = path.read_bytes()
        run(directory, "-r", "0")
        assert path.read_bytes().startswith(original)
        assert len(read_dynvec(path)) > len(serial)
        # Enabling diagnostics on a restart must create the metadata too.
        path.unlink()
        run(directory, "-r", "0")
        read_dynvec(path)
    if args.mpirun:
        with tempfile.TemporaryDirectory() as directory:
            run(directory, mpi=True)
            parallel = read_dynvec(Path(directory) / filename)
            assert len(serial) == len(parallel)
            for (st, sv), (pt, pv) in zip(serial, parallel):
                assert math.isclose(st, pt, rel_tol=1e-12, abs_tol=1e-20)
                assert all(math.isclose(s, p, rel_tol=1e-12) for s, p in zip(sv, pv))
    print("Frequency metadata, values, opt-out, and restart checks passed."
          + (" Serial/MPI agreement passed." if args.mpirun else ""))


if __name__ == "__main__":
    main()
